package Board

var advanceSizes = [...]float32{9, 10, 11, 12, 13, 14, 15, 16}

func weightCol(weight uint8) int {
	switch {
	case weight >= 7:
		return 2
	case weight >= 6:
		return 1
	}
	return 0
}

func runeW(r rune, px float32, col int) float32 {
	a, ok := advance[r]
	if !ok {
		return px * 0.6
	}
	at := func(i int) float32 { return a[i*3+col] }
	last := len(advanceSizes) - 1
	switch {
	case px <= advanceSizes[0]:
		return at(0) * px / advanceSizes[0]
	case px >= advanceSizes[last]:
		return at(last) * px / advanceSizes[last]
	}
	i := int(px - advanceSizes[0])
	t := (px - advanceSizes[i]) / (advanceSizes[i+1] - advanceSizes[i])
	return at(i) + (at(i+1)-at(i))*t
}

func TextW(s string, px float32, weight uint8) float32 {
	col := weightCol(weight)
	var w float32
	for _, r := range s {
		w += runeW(r, px, col)
	}
	return w
}

